(48305,0,0,0,0,0,0,0,0,'Did you triumph in Antorus?',0),
(48306,0,0,0,0,0,0,0,0,'Did you triumph in Antorus?',0),
(48318,2,0,0,0,0,0,0,0,'Спасибо за помощь, алхимик. Нам очень нужны были эти зелья.',25961),
(48323,2,0,0,0,0,0,0,0,'Спасибо за помощь, алхимик. Нам очень нужны были эти зелья.',25961),
(48337,2,0,0,0,0,0,0,0,'Спасибо за помощь, травник. Нам очень нужен был этот астральный вьюнок.',25961),
(48338,2,0,0,0,0,0,0,0,'',25961),
(48344,1,0,0,0,0,0,0,0,'Сейчас у нас нет права на ошибку, $n.',25549),
